    reject('title must be a non-empty string');
  }
  if (typeof description !== 'string' || description.length === 0) {
    reject('description must be a non-empty string');
  }

  const finalPriority = priority === undefined ? 'normal' : priority;
  if (!['low', 'normal', 'high'].includes(finalPriority)) {
    reject('priority must be one of low, normal, high');
