const tools = [
  {
    name: 'ticket_create',
    description: 'Create a support ticket.',
    inputSchema: {
      type: 'object',
      additionalProperties: false,
      properties: {
        title: { type: 'string', minLength: 1 },
        description: { type: 'string', minLength: 1 },
        priority: { type: 'string', enum: ['low', 'normal', 'high'] },
      },
      required: ['title', 'description'],
    },
  },
];

let nextId = 1;

function reject(message) {
  throw new Error(message);
}

export async function listTools() {
  return tools;
}

export async function callTool(name, args) {
  if (name !== 'ticket_create') {
    reject('Method not found');
  }

  const allowed = new Set(['title', 'description', 'priority']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      reject(`Unknown field: ${key}`);
    }
  }

  const { title, description, priority } = args;

  if (typeof title !== 'string' || title.length === 0) {
    reject('title must be a non-empty string');
  }
  if (typeof description !== 'string' || description.length === 0) {
    reject('description must be a non-empty string');
  }

  const finalPriority = priority === undefined ? 'normal' : priority;
  if (!['low', 'normal', 'high'].includes(finalPriority)) {
    reject('priority must be one of low, normal, high');
  }

  const id = `t${nextId++}`;
  const text = `Created ticket ${id} (priority: ${finalPriority}): ${title}`;
  return { content: [{ type: 'text', text }] };
}

